 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            q.append((ny, nx))
            comps.append(comp)
    template = max(comps, key=len)
    r0 = min(r for r, c in template)
    r1 = max(r for r, c in template)
    c0 = min(c for r, c in template)
    c1 = max(c for r, c in template)
    th, tw = r1 - r0 + 1, c1 - c0 + 1
    patch = [(r - r0, c - c0, grid[r][c]) for r, c in template]
    markers = [comp[0] for comp in comps if len(comp) == 1 and comp is not template]
    # All non-template singleton components are target markers.
    out = [row[:] for row in grid]
    for r, c in markers:
        out[r][c] = bg
    for mr, mc in markers:
        top, left = mr - th // 2, mc - tw // 2
        for dr, dc, color in patch:
            rr, cc = top + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out


if __name__ == '__main__':
    pass
